CommitDate: Thu Aug 22 11:10:36 2024 +0100

    Bug 1914318 - Port bug 1913322: Make arrowscrollbox use resizeobserver rather than overflow/underflow events. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D219837

diff --git a/mail/base/content/messenger.xhtml b/mail/base/content/messenger.xhtml
index bd23a010270..2f643dd97af 100644
--- a/mail/base/content/messenger.xhtml
+++ b/mail/base/content/messenger.xhtml
@@ -515,7 +515,7 @@
         <arrowscrollbox id="tabmail-arrowscrollbox"
                         orient="horizontal"
                         flex="1"
-                        clicktoscroll="true"
+                        clicktoscroll=""
                         style="min-width: 1px;">
           <tab is="tabmail-tab" selected="true"
                class="tabmail-tab" crop="end"/>
diff --git a/mail/base/content/widgets/tabmail-tabs.js b/mail/base/content/widgets/tabmail-tabs.js
index b2662886474..1482c47f29e 100644
--- a/mail/base/content/widgets/tabmail-tabs.js
+++ b/mail/base/content/widgets/tabmail-tabs.js
@@ -424,8 +424,8 @@
       // they would also get called for the all-tabs popup scrollbox.
       // Also, we can't rely on event.target because these are all
       // anonymous nodes.
-      this.arrowScrollbox.shadowRoot.addEventListener("overflow", this);
-      this.arrowScrollbox.shadowRoot.addEventListener("underflow", this);
+      this.arrowScrollbox.addEventListener("overflow", this);
+      this.arrowScrollbox.addEventListener("underflow", this);

       this.addEventListener("select", event => {
         this._handleTabSelect();
@@ -554,12 +554,7 @@
         case "overflow":
           this.arrowScrollbox.ensureElementIsVisible(this.selectedItem);

-          // filter overflow events which were dispatched on nested scrollboxes
-          // and ignore vertical events.
-          if (
-            aEvent.target != this.arrowScrollbox.scrollbox ||
-            aEvent.detail == 0
-          ) {
+          if (aEvent.target != this.arrowScrollbox) {
             return;
           }

@@ -567,12 +562,7 @@
           alltabsButton.removeAttribute("hidden");
           break;
         case "underflow":
-          // filter underflow events which were dispatched on nested scrollboxes
-          // and ignore vertical events.
-          if (
-            aEvent.target != this.arrowScrollbox.scrollbox ||
-            aEvent.detail == 0
-          ) {
+          if (aEvent.target != this.arrowScrollbox) {
             return;
           }

